-- Canonical applied cycles: drafts mutable with optimistic concurrency, entries append-only.
alter table public.vc_university_application_cycles drop constraint vc_university_application_cycles_status_check;
alter table public.vc_university_application_cycles alter column status set default 'setup';
alter table public.vc_university_application_cycles add constraint vc_university_application_cycles_status_check check(status in('draft','completed','abandoned','setup','active','paused','resumed','awaiting_weekly_review','final_reflection','submitted','under_review','revision_requested','resubmitted','approved','closed_incomplete'));
alter table public.vc_university_application_cycles
 add column drafts jsonb not null default '{}' check(jsonb_typeof(drafts)='object' and octet_length(drafts::text)<=65536),
 add column draft_version integer not null default 0 check(draft_version>=0),
 add column paused_at timestamptz, add column resumed_at timestamptz, add column operational_deadline timestamptz,
 add column revision_deadline timestamptz, add column closed_at timestamptz,
 add column special_review_required boolean not null default false,
 add column evidence_submission_id uuid references public.vc_university_evidence_submissions(submission_id),
 add constraint cycle_deadline_start check(operational_deadline is null or operational_deadline>started_at);
create index cycle_evidence_idx on public.vc_university_application_cycles(evidence_submission_id);
alter table public.vc_university_application_cycle_entries add column request_id uuid;
create unique index cycle_entry_request_idx on public.vc_university_application_cycle_entries(application_cycle_id,request_id) where request_id is not null;
alter table public.vc_university_evidence_reviews add column criterion_points jsonb, add column total_points numeric check(total_points between 0 and 100), add column structured_feedback jsonb;
-- Cycle definition configuration is immutable once published or used.
create function public.vc_university_guard_cycle_version() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if old.status in('published','archived') or exists(select 1 from public.vc_university_application_cycles where cycle_version_id=old.cycle_version_id) then
 if tg_op='DELETE' or (to_jsonb(new)-'status') is distinct from (to_jsonb(old)-'status') or new.status not in('published','archived') or (old.status='archived' and new.status<>'archived') then raise exception 'cycle_version_immutable';end if;
 end if;return case when tg_op='DELETE' then old else new end;
end $$;
create trigger cycle_version_guard before update or delete on public.vc_university_application_cycle_versions for each row execute function public.vc_university_guard_cycle_version();

create function public.vc_university_cycle_audit(p_actor uuid,p_cycle uuid,p_event text,p_meta jsonb default '{}') returns void language sql security invoker set search_path='' as $$
 insert into public.vc_university_academic_audit_log(actor_id,action,entity_type,entity_id,after_state) values(p_actor,p_event,'application_cycle',p_cycle::text,p_meta);
$$;
create function public.vc_university_cycle_state(p_cycle uuid) returns text language plpgsql security invoker set search_path='' as $$
declare c public.vc_university_application_cycles%rowtype; cfg jsonb; phase jsonb; day numeric;
begin
 select * into c from public.vc_university_application_cycles where application_cycle_id=p_cycle for update;
 if c.application_cycle_id is null then return 'not_started';end if;
 if c.status in('submitted','resubmitted','under_review','approved','closed_incomplete','completed','abandoned') then return c.status;end if;
 if c.status='revision_requested' then
 if c.special_review_required then return c.status;end if;
 if now()>c.revision_deadline then update public.vc_university_application_cycles set status='closed_incomplete',closed_at=now() where application_cycle_id=p_cycle;return 'closed_incomplete';end if;
 return c.status;end if;
 if c.started_at is null then return 'setup';end if;
 if now()>c.operational_deadline then update public.vc_university_application_cycles set status='closed_incomplete',closed_at=now() where application_cycle_id=p_cycle;return 'closed_incomplete';end if;
 if c.status='paused' then return 'paused';end if;
 select configuration into cfg from public.vc_university_application_cycle_versions where cycle_version_id=c.cycle_version_id;
 day:=extract(epoch from(now()-c.started_at))/86400;
 if day>= (cfg->>'duration_days')::integer then update public.vc_university_application_cycles set status='final_reflection' where application_cycle_id=p_cycle;return 'final_reflection';end if;
 for phase in select value from jsonb_array_elements(cfg->'phases') loop
 if day >= (phase->>'end')::integer and not exists(select 1 from public.vc_university_application_cycle_entries where application_cycle_id=p_cycle and entry_type='weekly_review' and entry_key=phase->>'key') then
 update public.vc_university_application_cycles set status='awaiting_weekly_review' where application_cycle_id=p_cycle;return 'awaiting_weekly_review';end if;end loop;
 return case when c.status='resumed' then 'resumed' else 'active' end;
end $$;
create function public.vc_university_cycle_read(p_actor uuid,p_enrollment uuid) returns jsonb language plpgsql security invoker set search_path='' as $$
declare e public.vc_university_enrollments%rowtype; v public.vc_university_application_cycle_versions%rowtype; c public.vc_university_application_cycles%rowtype; state text;
begin
 select * into e from public.vc_university_enrollments where enrollment_id=p_enrollment and user_id=p_actor and status='active';if e.enrollment_id is null then raise exception 'cycle_context_denied';end if;
 select * into v from public.vc_university_application_cycle_versions where course_id=e.course_id and course_version=e.course_version and status='published' order by created_at desc limit 1;
 if v.cycle_version_id is null then return jsonb_build_object('unavailable',true);end if;
 select * into c from public.vc_university_application_cycles where enrollment_id=p_enrollment and cycle_version_id=v.cycle_version_id;
 if c.application_cycle_id is not null then state:=public.vc_university_cycle_state(c.application_cycle_id);select * into c from public.vc_university_application_cycles where application_cycle_id=c.application_cycle_id;else state:='not_started';end if;
 return jsonb_build_object('definition',v.configuration,'cycle',case when c.application_cycle_id is null then null else to_jsonb(c) end,'state',state,
 'eligibility',jsonb_build_object('setup',exists(select 1 from public.vc_university_module_progress where enrollment_id=p_enrollment and module_no=(v.configuration->>'setup_after_module')::integer and completed_at is not null),'start',exists(select 1 from public.vc_university_module_progress where enrollment_id=p_enrollment and module_no=(v.configuration->>'start_after_module')::integer and completed_at is not null)),
 'entries',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at) from public.vc_university_application_cycle_entries x where x.application_cycle_id=c.application_cycle_id),'[]'),
 'evidence',case when c.evidence_submission_id is null then null else (select jsonb_build_object('submission_id',s.submission_id,'status',s.status,'current_revision',s.current_revision,'reviews',coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at) from public.vc_university_evidence_reviews r where r.submission_id=s.submission_id),'[]')) from public.vc_university_evidence_submissions s where s.submission_id=c.evidence_submission_id) end);
end $$;

create function public.vc_university_cycle_entry(p_actor uuid,p_cycle uuid,p_type text,p_key text,p_payload jsonb,p_request uuid) returns uuid language plpgsql security invoker set search_path='' as $$
declare old public.vc_university_application_cycle_entries%rowtype; id uuid;
begin
 if p_request is null then raise exception 'cycle_request_id_required';end if;
 select * into old from public.vc_university_application_cycle_entries where application_cycle_id=p_cycle and request_id=p_request;
 if old.cycle_entry_id is not null then if old.payload is distinct from p_payload or old.entry_type<>p_type or old.entry_key<>p_key then raise exception 'idempotency_payload_conflict';end if;return old.cycle_entry_id;end if;
 select * into old from public.vc_university_application_cycle_entries where application_cycle_id=p_cycle and entry_type=p_type and entry_key=p_key order by revision desc limit 1;
 insert into public.vc_university_application_cycle_entries(application_cycle_id,entry_type,entry_key,revision,supersedes_entry_id,payload,created_by,request_id)
 values(p_cycle,p_type,p_key,coalesce(old.revision,0)+1,old.cycle_entry_id,p_payload,p_actor,p_request) returning cycle_entry_id into id;return id;
end $$;
create function public.vc_university_cycle_integrator(p_cycle uuid,p_selected jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare c public.vc_university_application_cycles%rowtype; v public.vc_university_application_cycle_versions%rowtype; snap jsonb; phase jsonb; tool record; count integer;
begin
 select * into c from public.vc_university_application_cycles where application_cycle_id=p_cycle;
 select * into v from public.vc_university_application_cycle_versions where cycle_version_id=c.cycle_version_id;
 if now()<c.started_at+make_interval(days=>v.duration_days) then raise exception 'cycle_duration_pending';end if;
 for phase in select value from jsonb_array_elements(v.configuration->'phases') loop if not exists(select 1 from public.vc_university_application_cycle_entries where application_cycle_id=p_cycle and entry_type='weekly_review' and entry_key=phase->>'key') then raise exception 'weekly_reviews_pending';end if;end loop;
 if not exists(select 1 from public.vc_university_application_cycle_entries where application_cycle_id=p_cycle and entry_type='final_reflection') then raise exception 'final_reflection_pending';end if;
 if jsonb_typeof(p_selected) is distinct from 'array' or jsonb_array_length(p_selected)>100 or exists(select 1 from jsonb_array_elements_text(p_selected) x where not exists(select 1 from public.vc_university_application_cycle_entries en where en.application_cycle_id=p_cycle and en.entry_type='log' and en.cycle_entry_id::text=x and not exists(select 1 from public.vc_university_application_cycle_entries newer where newer.supersedes_entry_id=en.cycle_entry_id))) then raise exception 'selected_logs_invalid';end if;
 for tool in select key,value from jsonb_each_text(v.configuration->'required_applications') loop
 select count(*) into count from public.vc_university_application_cycle_entries x where x.application_cycle_id=p_cycle and x.entry_type='log' and x.payload->>'ferramenta'=tool.key and x.cycle_entry_id::text in(select jsonb_array_elements_text(p_selected)) and not exists(select 1 from public.vc_university_application_cycle_entries newer where newer.supersedes_entry_id=x.cycle_entry_id);
 if count<tool.value::integer then raise exception 'required_applications_pending';end if;end loop;
 select jsonb_build_object('cycle_id',p_cycle,'cycle_version_id',c.cycle_version_id,'started_at',c.started_at,'duration_days',v.duration_days,'objetivos_e_versoes',coalesce((select jsonb_agg(jsonb_build_object('revision',revision,'date',created_at,'payload',payload) order by revision) from public.vc_university_application_cycle_entries where application_cycle_id=p_cycle and entry_type='objective'),'[]'),
 'registros_relevantes',coalesce((select jsonb_agg(jsonb_build_object('id',cycle_entry_id,'revision',revision,'payload',payload)) from public.vc_university_application_cycle_entries where application_cycle_id=p_cycle and entry_type='log' and cycle_entry_id::text in(select jsonb_array_elements_text(p_selected))),'[]'),
 'revisoes_semanais',(select jsonb_agg(jsonb_build_object('phase',entry_key,'revision',revision,'payload',payload)) from public.vc_university_application_cycle_entries x where application_cycle_id=p_cycle and entry_type='weekly_review' and not exists(select 1 from public.vc_university_application_cycle_entries newer where newer.supersedes_entry_id=x.cycle_entry_id)),
 'reflexao_final',(select payload from public.vc_university_application_cycle_entries where application_cycle_id=p_cycle and entry_type='final_reflection' order by revision desc limit 1)) into snap;
 if octet_length(snap::text)>65536 then raise exception 'integrator_size_limit';end if;return snap;
end $$;
create function public.vc_university_cycle_write(p_actor uuid,p_enrollment uuid,p_action text,p_payload jsonb,p_expected_version integer,p_request uuid default null,p_key text default null) returns jsonb language plpgsql security invoker set search_path='' as $$
declare e public.vc_university_enrollments%rowtype; v public.vc_university_application_cycle_versions%rowtype; c public.vc_university_application_cycles%rowtype; s public.vc_university_evidence_submissions%rowtype; d public.vc_university_evidence_definition_versions%rowtype; rev public.vc_university_evidence_revisions%rowtype; en public.vc_university_application_cycle_entries%rowtype; phase jsonb; state text; typ text; key text; id uuid; snapshot jsonb; previous jsonb; event text;
begin
 if p_action not in('setup_draft','weekly_draft','final_draft','start','goal_revise','pause','resume','log','weekly_complete','final_complete','submit') or jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>65536 then raise exception 'invalid_cycle_request';end if;
 select * into e from public.vc_university_enrollments where enrollment_id=p_enrollment and user_id=p_actor and status='active';if e.enrollment_id is null then raise exception 'cycle_context_denied';end if;
 select * into v from public.vc_university_application_cycle_versions where course_id=e.course_id and course_version=e.course_version and status='published' order by created_at desc limit 1;if v.cycle_version_id is null then raise exception 'cycle_definition_unavailable';end if;
 perform pg_advisory_xact_lock(hashtext(p_enrollment::text||':'||v.cycle_version_id::text));
 select * into c from public.vc_university_application_cycles where enrollment_id=p_enrollment and cycle_version_id=v.cycle_version_id for update;
 if c.application_cycle_id is null then
 if p_action<>'setup_draft' or p_expected_version<>0 then raise exception 'cycle_setup_required';end if;
 if not exists(select 1 from public.vc_university_module_progress where enrollment_id=p_enrollment and module_no=(v.configuration->>'setup_after_module')::integer and completed_at is not null) then raise exception 'cycle_setup_ineligible';end if;
 insert into public.vc_university_application_cycles(cycle_version_id,enrollment_id,learner_id) values(v.cycle_version_id,p_enrollment,p_actor) returning * into c;
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,'cycle_setup_created',jsonb_build_object('status','setup'));
 end if;
 state:=public.vc_university_cycle_state(c.application_cycle_id);
 select * into c from public.vc_university_application_cycles where application_cycle_id=c.application_cycle_id;
 -- Same mutation request is safe to retry after any subsequent state/version change.
 if p_request is not null and p_action in('start','goal_revise','log','weekly_complete','final_complete') then
 select * into en from public.vc_university_application_cycle_entries where application_cycle_id=c.application_cycle_id and request_id=p_request;
 if en.cycle_entry_id is not null then if en.payload is distinct from p_payload then raise exception 'idempotency_payload_conflict';end if;return public.vc_university_cycle_read(p_actor,p_enrollment);end if;end if;
 if p_action='submit' and c.evidence_submission_id is not null then
 select * into rev from public.vc_university_evidence_revisions where submission_id=c.evidence_submission_id and request_id=p_request;
 if rev.evidence_revision_id is not null then if rev.structured_data->'selected_entry_ids' is distinct from p_payload->'selected_entry_ids' then raise exception 'idempotency_payload_conflict';end if;return public.vc_university_cycle_read(p_actor,p_enrollment);end if;end if;
 if c.draft_version is distinct from p_expected_version then raise exception 'draft_version_conflict';end if;
 if state in('approved','closed_incomplete','submitted','resubmitted','under_review','completed','abandoned') then raise exception 'cycle_locked';end if;
 if c.special_review_required then raise exception 'pedagogical_review_required';end if;
 if p_action like '%_draft' then
 typ:=case p_action when 'setup_draft' then 'setup' when 'weekly_draft' then 'weekly_review' else 'final_reflection' end;
 if typ='setup' and state<>'setup' then raise exception 'cycle_transition_denied';end if;
 if typ<>'setup' and (c.started_at is null or state='paused') then raise exception 'cycle_transition_denied';end if;
 key:=case when typ='weekly_review' then 'weekly-'||coalesce(p_key,'') else typ end;
 if typ='weekly_review' and not exists(select 1 from jsonb_array_elements(v.configuration->'phases') ph where ph->>'key'=p_key) then raise exception 'cycle_entry_key_invalid';end if;
 if typ='weekly_review' and exists(select 1 from public.vc_university_application_cycle_entries where application_cycle_id=c.application_cycle_id and entry_type=typ and entry_key=p_key) then raise exception 'weekly_review_immutable';end if;
 update public.vc_university_application_cycles set drafts=jsonb_set(drafts,array[key],p_payload,true),draft_version=draft_version+1 where application_cycle_id=c.application_cycle_id;
 elsif p_action='start' then
 if state<>'setup' or not exists(select 1 from public.vc_university_module_progress where enrollment_id=p_enrollment and module_no=(v.configuration->>'start_after_module')::integer and completed_at is not null) then raise exception 'cycle_start_ineligible';end if;
 if not public.vc_university_validate_evidence(v.configuration->'forms'->'setup',p_payload) then raise exception 'cycle_structure_invalid';end if;
 id:=public.vc_university_cycle_entry(p_actor,c.application_cycle_id,'objective','principal',p_payload,p_request);
 update public.vc_university_application_cycles set status='active',started_at=now(),operational_deadline=now()+make_interval(days=>(v.configuration->>'window_days')::integer),draft_version=draft_version+1 where application_cycle_id=c.application_cycle_id;
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,'cycle_started',jsonb_build_object('entry_id',id,'status','active'));
 elsif p_action='pause' then
 if state not in('active','resumed','awaiting_weekly_review','final_reflection') or coalesce(p_payload->>'reason','') not in('rotina','disponibilidade','seguranca','outro','prefiro_nao_informar') or p_payload-'reason'<>'{}'::jsonb then raise exception 'cycle_transition_denied';end if;
 update public.vc_university_application_cycles set status='paused',paused_at=now(),draft_version=draft_version+1 where application_cycle_id=c.application_cycle_id;
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,'cycle_paused',jsonb_build_object('reason',p_payload->>'reason','status','paused'));
 elsif p_action='resume' then
 if state<>'paused' then raise exception 'cycle_transition_denied';end if;
 update public.vc_university_application_cycles set status='resumed',resumed_at=now(),draft_version=draft_version+1 where application_cycle_id=c.application_cycle_id;
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,'cycle_resumed',jsonb_build_object('status','resumed'));
 elsif p_action='goal_revise' then
 if state not in('active','resumed','awaiting_weekly_review','final_reflection') or length(btrim(p_payload->>'motivo_alteracao')) not between 3 and 1200 then raise exception 'cycle_transition_denied';end if;
 if (select count(*) from public.vc_university_application_cycle_entries where application_cycle_id=c.application_cycle_id and entry_type='objective')>(v.configuration->>'goal_change_limit')::integer then raise exception 'goal_change_limit_reached';end if;
 if not public.vc_university_validate_evidence(v.configuration->'forms'->'setup',p_payload-'motivo_alteracao') then raise exception 'cycle_structure_invalid';end if;
 id:=public.vc_university_cycle_entry(p_actor,c.application_cycle_id,'objective','principal',p_payload,p_request);
 update public.vc_university_application_cycles set draft_version=draft_version+1 where application_cycle_id=c.application_cycle_id;
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,'cycle_goal_revised',jsonb_build_object('entry_id',id));
 elsif p_action in('log','weekly_complete','final_complete') then
 if state not in('active','resumed','awaiting_weekly_review','final_reflection','revision_requested') then raise exception 'cycle_transition_denied';end if;
 typ:=case p_action when 'log' then 'log' when 'weekly_complete' then 'weekly_review' else 'final_reflection' end;
 key:=case when typ='final_reflection' then 'final' else p_key end;
 if key is null or key !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or length(key)>80 then raise exception 'cycle_entry_key_invalid';end if;
 if not public.vc_university_validate_evidence(v.configuration->'forms'->typ,p_payload) then raise exception 'cycle_structure_invalid';end if;
 if typ='log' then
 if p_payload->>'data' !~ '^\d{4}-\d{2}-\d{2}$' or (p_payload->>'data')::date<c.started_at::date or (p_payload->>'data')::date>least(now()::date,c.operational_deadline::date) then raise exception 'cycle_log_date_invalid';end if;
 select payload into previous from public.vc_university_application_cycle_entries where application_cycle_id=c.application_cycle_id and entry_type='objective' order by revision desc limit 1;
 for i in 1..3 loop if coalesce(p_payload->>('indicador_'||i),'')<>'' and not exists(select 1 from generate_series(1,3) n where previous->>('indicador_'||n)=p_payload->>('indicador_'||i)) then raise exception 'cycle_indicator_invalid';end if;end loop;
 elsif typ='weekly_review' then
 select value into phase from jsonb_array_elements(v.configuration->'phases') where value->>'key'=key;
 if phase is null or now()<c.started_at+make_interval(days=>(phase->>'end')::integer) then raise exception 'weekly_review_not_due';end if;
 if exists(select 1 from public.vc_university_application_cycle_entries where application_cycle_id=c.application_cycle_id and entry_type=typ and entry_key=key) and state<>'revision_requested' then raise exception 'weekly_review_immutable';end if;
 elsif now()<c.started_at+make_interval(days=>v.duration_days) then raise exception 'cycle_duration_pending';end if;
 id:=public.vc_university_cycle_entry(p_actor,c.application_cycle_id,typ,key,p_payload,p_request);
 update public.vc_university_application_cycles set draft_version=draft_version+1,status=case when status='awaiting_weekly_review' then 'active' else status end where application_cycle_id=c.application_cycle_id;
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,case typ when 'log' then 'cycle_log_created' when 'weekly_review' then 'weekly_review_completed' else 'cycle_final_reflection_completed' end,jsonb_build_object('entry_id',id));
 elsif p_action='submit' then
 if state not in('final_reflection','revision_requested') or p_request is null or p_payload->>'privacy_confirmed' is distinct from 'true' or p_payload-array['privacy_confirmed','selected_entry_ids']<>'{}'::jsonb then raise exception 'cycle_transition_denied';end if;
 snapshot:=public.vc_university_cycle_integrator(c.application_cycle_id,p_payload->'selected_entry_ids')||jsonb_build_object('selected_entry_ids',p_payload->'selected_entry_ids');
 select dv.* into d from public.vc_university_evidence_definition_versions dv join public.vc_university_evidence_definitions def using(evidence_definition_id) where dv.course_id=e.course_id and dv.course_version=e.course_version and dv.status='published' and def.evidence_key=v.configuration->>'final_evidence_key' and dv.validation_mode='human_required';
 if d.evidence_definition_version_id is null then raise exception 'evidence_definition_unavailable';end if;
 select * into s from public.vc_university_evidence_submissions where submission_id=c.evidence_submission_id;
 if s.submission_id is null then insert into public.vc_university_evidence_submissions(enrollment_id,learner_id,course_id,course_version,evidence_definition_version_id) values(p_enrollment,p_actor,e.course_id,e.course_version,d.evidence_definition_version_id) returning * into s;end if;
 if s.current_revision> (v.configuration->>'included_revisions')::integer+c.special_revisions_granted then raise exception 'pedagogical_review_required';end if;
 insert into public.vc_university_evidence_revisions(submission_id,revision,content,structured_data,authored_by,request_id) values(s.submission_id,s.current_revision+1,'Structured evidence; see structured_data',snapshot,p_actor,p_request) returning * into rev;
 event:=case when s.current_revision=0 then 'e10_submitted' else 'e10_resubmitted' end;
 state:=case when s.current_revision=0 then 'submitted' else 'resubmitted' end;
 update public.vc_university_evidence_submissions set status=state,current_revision=s.current_revision+1,submitted_at=now(),review_selected=true,updated_at=now() where submission_id=s.submission_id;
 update public.vc_university_application_cycles set status=state,evidence_submission_id=s.submission_id,draft_version=draft_version+1 where application_cycle_id=c.application_cycle_id;
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,event,jsonb_build_object('submission_id',s.submission_id,'revision_id',rev.evidence_revision_id,'status',state));
 end if;
 return public.vc_university_cycle_read(p_actor,p_enrollment);
end $$;
alter table public.vc_university_application_cycles add column special_revisions_granted integer not null default 0 check(special_revisions_granted between 0 and 10);
create function public.vc_university_cycle_review(p_actor uuid,p_submission uuid,p_revision uuid,p_points jsonb,p_feedback jsonb,p_action text default 'evaluate') returns jsonb language plpgsql security invoker set search_path='' as $$
declare c public.vc_university_application_cycles%rowtype; s public.vc_university_evidence_submissions%rowtype; v public.vc_university_application_cycle_versions%rowtype; criterion jsonb; val numeric; total numeric:=0; decision text; current_id uuid; key text;
begin
 select * into s from public.vc_university_evidence_submissions where submission_id=p_submission for update;
 if not vc_private.vc_university_teacher_can_review(p_actor,p_submission) then raise exception 'evidence_review_denied';end if;
 select * into c from public.vc_university_application_cycles where evidence_submission_id=p_submission for update;
 if c.application_cycle_id is null then raise exception 'cycle_context_denied';end if;
 select * into v from public.vc_university_application_cycle_versions where cycle_version_id=c.cycle_version_id;
 select evidence_revision_id into current_id from public.vc_university_evidence_revisions where submission_id=p_submission and revision=s.current_revision;
 if current_id is distinct from p_revision then raise exception 'review_revision_stale';end if;
 if p_action='authorize_special_revision' then
 if not c.special_review_required or c.special_revisions_granted>=10 then raise exception 'review_state_conflict';end if;
 update public.vc_university_application_cycles set special_review_required=false,special_revisions_granted=special_revisions_granted+1,revision_deadline=now()+make_interval(days=>(v.configuration->>'revision_response_days')::integer) where application_cycle_id=c.application_cycle_id;
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,'cycle_special_revision_authorized',jsonb_build_object('revision_id',p_revision));
 return jsonb_build_object('status','revision_requested','special_review_required',false);end if;
 if p_action<>'evaluate' or s.status not in('submitted','resubmitted','under_review') or jsonb_typeof(p_points) is distinct from 'object' or jsonb_typeof(p_feedback) is distinct from 'object' then raise exception 'invalid_rubric_review';end if;
 for criterion in select value from jsonb_array_elements(v.configuration->'rubric'->'criteria') loop
 key:=criterion->>'key';if jsonb_typeof(p_points->key) is distinct from 'number' then raise exception 'invalid_rubric_review';end if;
 val:=(p_points->>key)::numeric;if val<0 or val>(criterion->>'max_points')::numeric then raise exception 'invalid_rubric_review';end if;total:=total+val;end loop;
 if (select count(*) from jsonb_object_keys(p_points))<>jsonb_array_length(v.configuration->'rubric'->'criteria') then raise exception 'invalid_rubric_review';end if;
 for key in select unnest(array['reconhecer_evidencia','localizar_lacuna','retornar_ao_criterio','orientar_proxima_acao']) loop
 if jsonb_typeof(p_feedback->key) is distinct from 'string' or length(btrim(p_feedback->>key)) not between 3 and 900 then raise exception 'invalid_rubric_review';end if;end loop;
 if (select count(*) from jsonb_object_keys(p_feedback))<>4 then raise exception 'invalid_rubric_review';end if;
 decision:=case when total>=(v.configuration->'rubric'->>'pass_points')::numeric then 'approved' else 'revision_requested' end;
 insert into public.vc_university_evidence_reviews(submission_id,evidence_revision_id,reviewer_id,decision,feedback,rubric_version,criterion_points,total_points,structured_feedback)
 values(p_submission,p_revision,p_actor,decision,concat_ws(E'\n',p_feedback->>'reconhecer_evidencia',p_feedback->>'localizar_lacuna',p_feedback->>'retornar_ao_criterio',p_feedback->>'orientar_proxima_acao'),v.configuration->'rubric'->>'version',p_points,total,p_feedback);
 update public.vc_university_evidence_submissions set status=decision,approved_at=case when decision='approved' then now() else null end,updated_at=now() where submission_id=p_submission;
 update public.vc_university_application_cycles set status=decision,completed_at=case when decision='approved' then now() else null end,
 revision_deadline=case when decision='revision_requested' then now()+make_interval(days=>(v.configuration->>'revision_response_days')::integer) else null end,
 special_review_required=decision='revision_requested' and s.current_revision>=1+(v.configuration->>'included_revisions')::integer+c.special_revisions_granted where application_cycle_id=c.application_cycle_id;
 perform public.vc_university_evidence_requirement(p_submission,decision='approved');
 perform public.vc_university_cycle_audit(p_actor,c.application_cycle_id,case when decision='approved' then 'e10_approved' else 'e10_revision_requested' end,jsonb_build_object('submission_id',p_submission,'revision_id',p_revision,'status',decision,'points',total));
 return jsonb_build_object('status',decision,'total_points',total,'revision_id',p_revision);
end $$;
-- Rubric-mandatory evidence cannot use the generic teacher approval shortcut.
create function public.vc_university_guard_rubric_review() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if exists(select 1 from public.vc_university_evidence_submissions s join public.vc_university_evidence_definition_versions d using(evidence_definition_version_id) where s.submission_id=new.submission_id and d.validation_policy->>'rubric_required'='true') and (new.criterion_points is null or new.total_points is null or new.structured_feedback is null) then raise exception 'mandatory_rubric_required';end if;return new;
end $$;
create trigger evidence_rubric_required before insert on public.vc_university_evidence_reviews for each row execute function public.vc_university_guard_rubric_review();
-- Column ACL protects draft content; own-cycle RLS already excludes teachers, owners and B2B.
revoke all on public.vc_university_application_cycles,public.vc_university_application_cycle_entries from anon,authenticated;
grant select on public.vc_university_application_cycles,public.vc_university_application_cycle_entries to authenticated;
-- Functions are service-only. Identity/context still checked in every public operation.
create or replace function public.vc_university_evidence_requirement(p_submission uuid,p_satisfied boolean)
returns void language plpgsql security invoker set search_path='' as $$
declare s public.vc_university_evidence_submissions%rowtype; r record; rev uuid;
begin
 select * into s from public.vc_university_evidence_submissions where submission_id=p_submission;
 select evidence_revision_id into rev from public.vc_university_evidence_revisions where submission_id=p_submission and revision=s.current_revision;
 for r in select mr.* from public.vc_university_module_requirements mr
 join public.vc_university_evidence_definition_versions dv on dv.evidence_definition_version_id=s.evidence_definition_version_id
 join public.vc_university_evidence_definitions d on d.evidence_definition_id=dv.evidence_definition_id
 join public.vc_university_module_versions mv on mv.module_id=d.module_id and mv.course_id=s.course_id and mv.course_version=s.course_version
 where mr.module_version_id=mv.module_version_id and mr.status='published' and mr.requirement_type in('evidence_completed','final_project_approved')
 and (mr.requirement_type<>'final_project_approved' or not p_satisfied or s.status='approved')
 and mr.configuration->>'evidence_definition_version_id'=dv.evidence_definition_version_id::text loop
 insert into public.vc_university_requirement_progress(enrollment_id,requirement_id,status,source_type,source_id,satisfied_at)
 values(s.enrollment_id,r.requirement_id,case when p_satisfied then 'completed' else 'requirements_pending' end,'evidence_revision',rev::text,case when p_satisfied then now() else null end)
 on conflict(enrollment_id,requirement_id) do update set status=excluded.status,source_type=excluded.source_type,source_id=excluded.source_id,satisfied_at=excluded.satisfied_at,updated_at=now();
 if p_satisfied then
 insert into public.vc_university_academic_audit_log(actor_id,action,entity_type,entity_id,after_state)
 values(s.learner_id,'requirement_satisfied','requirement',r.requirement_id::text,jsonb_build_object('submission_id',p_submission,'revision_id',rev));
 -- Completion always goes through the approved PR2 engine.
 perform public.vc_university_complete_module_if_ready(s.enrollment_id,r.module_version_id);
 end if;
 end loop;
end $$;

create or replace function public.vc_university_evidence_queue(p_actor uuid,p_course text)
returns jsonb language sql stable security invoker set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('submission_id',s.submission_id,'status',s.status,'current_revision',s.current_revision,
 'evidence_revision_id',rev.evidence_revision_id,'structured_data',rev.structured_data,'definition',to_jsonb(d),'module_no',m.module_no,'submitted_at',s.submitted_at,'learner_id',s.learner_id,'cohort_id',e.cohort_id,'cohort_label',(select label from public.vc_university_cohorts where cohort_id=e.cohort_id),'special_review_required',coalesce(c.special_review_required,false),'history',coalesce((select jsonb_agg(jsonb_build_object('revision_id',er.evidence_revision_id,'revision',er.revision,'created_at',er.created_at)) from public.vc_university_evidence_revisions er where er.submission_id=s.submission_id),'[]'),'reviews',coalesce((select jsonb_agg(to_jsonb(rv) order by rv.created_at) from public.vc_university_evidence_reviews rv where rv.submission_id=s.submission_id),'[]'))), '[]'::jsonb)
 from public.vc_university_evidence_submissions s
 join public.vc_university_enrollments e using(enrollment_id)
 left join public.vc_university_application_cycles c on c.evidence_submission_id=s.submission_id
 join public.vc_university_evidence_definition_versions d on d.evidence_definition_version_id=s.evidence_definition_version_id
 join public.vc_university_evidence_definitions def on def.evidence_definition_id=d.evidence_definition_id
 join public.vc_university_modules m on m.module_id=def.module_id
 join public.vc_university_evidence_revisions rev on rev.submission_id=s.submission_id and rev.revision=s.current_revision
 where s.course_id=p_course and vc_private.vc_university_teacher_can_review(p_actor,s.submission_id);
$$;

