insert into public.vc_university_application_cycle_definitions(code,title,description) values('IE30','IE30','IE30 é o ciclo aplicado de 30 dias do curso Inteligência Emocional Aplicada, no qual o aluno escolhe um comportamento-alvo, planeja respostas, realiza aplicações no cotidiano, registra evidências relevantes, revisa o processo e constrói seu próximo ciclo de desenvolvimento.') on conflict(code) do nothing;
insert into public.vc_university_application_cycle_versions(cycle_definition_id,course_id,course_version,version,duration_days,requirements,configuration,status) select cycle_definition_id,'inteligencia-emocional-aplicada','1.0','1.0',30,'{"PAUSA": 3, "CLARO": 1, "DECIDE": 1}'::jsonb,'{"code": "IE30", "title": "IE30", "description": "IE30 é o ciclo aplicado de 30 dias do curso Inteligência Emocional Aplicada, no qual o aluno escolhe um comportamento-alvo, planeja respostas, realiza aplicações no cotidiano, registra evidências relevantes, revisa o processo e constrói seu próximo ciclo de desenvolvimento.", "version": "1.0", "duration_days": 30, "window_days": 45, "setup_after_module": 7, "start_after_module": 9, "goal_change_limit": 3, "included_revisions": 2, "revision_response_days": 14, "final_evidence_key": "e10", "required_applications": {"PAUSA": 3, "CLARO": 1, "DECIDE": 1}, "phases": [{"key": "observar", "label": "OBSERVAR", "start": 1, "end": 7, "objective": "Reconhecer contexto, sinais, resposta e consequência."}, {"key": "interromper", "label": "INTERROMPER", "start": 8, "end": 14, "objective": "Identificar oportunidades de PAUSA/alteração do automático."}, {"key": "substituir", "label": "SUBSTITUIR", "start": 15, "end": 21, "objective": "Experimentar resposta alternativa adequada."}, {"key": "consolidar", "label": "CONSOLIDAR", "start": 22, "end": 30, "objective": "Repetir, revisar e preparar próximo ciclo."}], "notes": ["30 dias são uma janela pedagógica de aplicação e observação, sem promessa de formação de hábito ou transformação psicológica.", "Sem obrigação diária. Ausências não zeram progresso.", "Teste da Câmera é uma heurística educacional: descreva algo observável.", "Pausa não altera a janela fixa de 45 dias.", "Após 30 dias, finalize até o dia 45. Uma entrega no prazo mantém o fluxo de revisão humana; cada parecer abre 14 dias para resposta."], "forms": {"setup": {"version": 1, "privacy_notice": "Compartilhe apenas as informações necessárias para demonstrar sua aprendizagem. Não informe nomes completos, documentos, diagnósticos, dados médicos, informações íntimas de terceiros, dados empresariais confidenciais ou qualquer informação que possa causar exposição indevida. Quando necessário, altere nomes, detalhes ou utilize um cenário equivalente.", "sections": [{"section_key": "alvo", "label": "Preparação · não inicia o dia 1", "repeatable": false, "fields": [{"field_key": "comportamento_alvo", "type": "textarea", "label": "Comportamento-alvo principal · observável, específico, realista e sob sua influência", "help_text": "Registre apenas informações necessárias e anonimizadas.", "required": true, "min": 3, "max": 1200, "privacy_hint": "Cenário seguro, anonimizado, simulado, retrospectivo ou hipotético.", "repeatable": false, "validation_rules": {"trim": true}}, {"field_key": "motivo", "type": "textarea", "label": "Motivo", "help_text": "Registre apenas informações necessárias e anonimizadas.", "required": true, "min": 3, "max": 1200, "privacy_hint": "Cenário seguro, anonimizado, simulado, retrospectivo ou hipotético.", "repeatable": false, "validation_rules": {"trim": true}}, {"field_key": "contexto_inicial", "type": "textarea", "label": "Contexto inicial", "help_text": "Registre apenas informações necessárias e anonimizadas.", "required": true, "min": 3, "max": 1200, "privacy_hint": "Cenário seguro, anonimizado, simulado, retrospectivo ou hipotético.", "repeatable": false, "validation_rules": {"trim": true}}]}, {"section_key": "contextos", "label": "Contextos e sinais · até três", "repeatable": false, "fields": [{"field_key": "contexto_1", "type": "textarea", "label": "Contexto 1", "help_text": "Registre apenas informações necessárias e anonimizadas.", "required": true, "min": 3, "max": 1200, "privacy_hint": "Cenário seguro, anonimizado, simulado, retrospectivo ou hipotético.", "repeatable": false, "validation_rules": {"trim": true}}, {"field_key": "contexto_2", "type": "textarea", "label": "Contexto 2", "h